import React from 'react';
import './pages.css';

const About = () => {
    return (
        <div className="page-container">
            <h2>About Emergency Contact App</h2>
            <p>
                The Emergency Contact App is designed to provide quick access to essential emergency services 
                in your area. Whether you need to contact the police, fire department, ambulance, or disaster 
                management, this app ensures you have the numbers you need at your fingertips.
            </p>
            <p>
                Users can also submit complaints or feedback through the Home page, helping authorities 
                respond more efficiently to incidents. The app combines modern React technologies such as 
                Redux for state management and Context API for user authentication to provide a smooth 
                and interactive experience.
            </p>
            <p>
                Our goal is to make emergency services more accessible and improve public safety for 
                everyone.
            </p>
        </div>
    );
};

export default About;
